package local.skyfamily;
import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
public class WordMazeActivity extends FamilyActivity {
 final String[] endings={"en","at","op","ip"};
 final String[][] familyWords={{"den","fen","hen","men","pen","ten","yen","wren","then","when"},{"bat","cat","fat","hat","mat","pat","rat","sat","chat","flat"},{"cop","hop","mop","pop","top","shop","stop","crop","drop","flop"},{"dip","hip","lip","rip","sip","tip","zip","chip","clip","drip"}};
 @Override void puzzle(){page("Word games");text("Offline puzzles / progress saved on this device");button("Word maze / follow the word family",()->maze(0));button("Daily mini crossword",()->crossword());button("Daily five-letter guess",()->guess());}
 void guess(){page("Daily five-letter guess");originalGuess();}
 void originalGuess(){String[] words={"APPLE","BEACH","SPACE","FRAME","TRAIN","CLOUD","PLANT","BRUSH","LIGHT","OCEAN","HOUSE","RIVER","GREEN","STONE"};long d=System.currentTimeMillis()/86400000L;String answer=words[(int)(d%words.length)],key="puzzle."+d;text("Six guesses. + correct place, ? elsewhere, - absent. UTC daily reset.");TextView history=new TextView(this);history.setTextColor(fg);history.setTextSize(22);history.setText(get(key));body.addView(history);EditText input=input("Five letters","");button("Guess",()->{String old=get(key);if(old.contains("+++++")||!old.isEmpty()&&old.split("\n").length>=6){toast("Today's puzzle is finished");return;}String g=input.getText().toString().trim().toUpperCase(Locale.US);if(!g.matches("[A-Z]{5}")){toast("Enter five letters");return;}char[] marks={'-','-','-','-','-'},left=answer.toCharArray();for(int i=0;i<5;i++)if(g.charAt(i)==left[i]){marks[i]='+';left[i]=' ';}for(int i=0;i<5;i++)if(marks[i]!='+')for(int j=0;j<5;j++)if(g.charAt(i)==left[j]){marks[i]='?';left[j]=' ';break;}String next=old+g+"  "+new String(marks)+"\n";save(key,next);history.setText(next);input.setText("");});}
 @Override void trail(){maze(0);}
 @Override void tile(String title,String subtitle,String mark,int color,Runnable action){if(title.equals("Daily word")||title.equals("Word games")){super.tile("Word games","Word maze, crossword and daily guess",mark,color,action);return;}super.tile(title,subtitle,mark,color,action);}
 void maze(int family){page("Word maze / -"+endings[family]);text("Start at the green cell. Tap connected words ending in -"+endings[family]+" to reach END. Walls block movement. Tap your previous word to go back.");LinearLayout choices=new LinearLayout(this);body.addView(choices);for(int i=0;i<endings.length;i++){final int selected=i;TextView choice=new TextView(this);choice.setText("-"+endings[i]);choice.setTextColor(i==family?bg:fg);choice.setTextSize(20);choice.setGravity(Gravity.CENTER);choice.setBackground(shape(i==family?accent:surface,edge,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(dp(3),0,dp(3),dp(10));choices.addView(choice,p);choice.setOnClickListener(v->maze(selected));}TextView status=new TextView(this);status.setTextColor(accent);status.setTextSize(18);body.addView(status);MazeBoard board=new MazeBoard(family,status);body.addView(board,new LinearLayout.LayoutParams(-1,dp(430)));button("Hint / take the next correct step",()->board.hint());button("Start again",()->{board.steps.clear();board.steps.add(0);board.persist();board.invalidate();});text("Accessible movement controls");button("Up",()->board.direction(0));button("Right",()->board.direction(1));button("Down",()->board.direction(2));button("Left",()->board.direction(3));text("A new original maze is generated from the local date and word family. Layout is not copied from the supplied worksheet. Words can repeat along longer paths.");}
 class MazeBoard extends View {
 final int n=6,total=36;int[] walls=new int[36];boolean[] visited=new boolean[36];ArrayList<Integer> solution=new ArrayList<>(),steps=new ArrayList<>();String[] labels=new String[36];int[] dx={0,1,0,-1},dy={-1,0,1,0};int family;String store;TextView status;Paint p=new Paint(3);Random random;float left,top,cell;
 MazeBoard(int f,TextView s){super(WordMazeActivity.this);family=f;status=s;store="maze.v1."+day()+"."+endings[f];random=new Random((day()+endings[f]).hashCode());for(int attempt=0;attempt<12;attempt++){Arrays.fill(walls,15);Arrays.fill(visited,false);carve(0);findPath();if(solution.size()>=16)break;}HashSet<Integer> correct=new HashSet<>(solution);ArrayList<String> distractors=new ArrayList<>();for(int i=0;i<familyWords.length;i++)if(i!=f)Collections.addAll(distractors,familyWords[i]);for(int i=0;i<total;i++)labels[i]=correct.contains(i)?familyWords[f][random.nextInt(familyWords[f].length)]:distractors.get(random.nextInt(distractors.size()));steps.add(0);for(String saved:get(store).split(",")){try{int v=Integer.parseInt(saved);if(v==0&&steps.size()==1)continue;if(steps.size()<solution.size()&&v==solution.get(steps.size()))steps.add(v);else break;}catch(Exception ignored){}}updateStatus();setContentDescription("Six by six word-family corridor maze. Use touch or the directional buttons below.");}
 int neighbor(int at,int direction){int x=at%n+dx[direction],y=at/n+dy[direction];return x<0||y<0||x>=n||y>=n?-1:y*n+x;}
 void carve(int at){visited[at]=true;ArrayList<Integer> dirs=new ArrayList<>(Arrays.asList(0,1,2,3));Collections.shuffle(dirs,random);for(int d:dirs){int other=neighbor(at,d);if(other>=0&&!visited[other]){walls[at]&=~(1<<d);walls[other]&=~(1<<((d+2)%4));carve(other);}}}
 void findPath(){int[] parent=new int[total];Arrays.fill(parent,-1);ArrayDeque<Integer> q=new ArrayDeque<>();q.add(0);parent[0]=0;while(!q.isEmpty()){int at=q.remove();for(int d=0;d<4;d++)if((walls[at]&(1<<d))==0){int next=neighbor(at,d);if(next>=0&&parent[next]<0){parent[next]=at;q.add(next);}}}solution.clear();int at=total-1;while(at!=0){solution.add(0,at);at=parent[at];}solution.add(0,0);}
 void updateStatus(){int here=steps.get(steps.size()-1);StringBuilder moves=new StringBuilder();String[] names={"up","right","down","left"};for(int d=0;d<4;d++)if((walls[here]&(1<<d))==0){int to=neighbor(here,d);if(to>=0)moves.append(names[d]).append(": ").append(labels[to]).append("   ");}status.setText(here==total-1?"Maze complete! You followed the -"+endings[family]+" family.":"Current: "+labels[here]+" / "+moves);}
 void persist(){StringBuilder s=new StringBuilder();for(int at:steps)s.append(at).append(',');save(store,s.toString());updateStatus();}
 void direction(int d){int here=steps.get(steps.size()-1);int next=neighbor(here,d);if(next<0||(walls[here]&(1<<d))!=0){toast("There is a wall that way");return;}move(next);}
 void move(int next){int here=steps.get(steps.size()-1);int direction=-1;for(int d=0;d<4;d++)if(neighbor(here,d)==next)direction=d;if(direction<0||(walls[here]&(1<<direction))!=0){toast("Follow an open corridor from your current word");return;}if(steps.size()>1&&next==steps.get(steps.size()-2)){steps.remove(steps.size()-1);}else if(!labels[next].endsWith(endings[family])){toast(labels[next]+" does not end in -"+endings[family]);return;}else if(!steps.contains(next)){steps.add(next);}persist();invalidate();if(next==total-1)toast("Word maze complete!");}
 void hint(){if(steps.size()>=solution.size()){toast("Already complete");return;}move(solution.get(steps.size()));}
 protected void onDraw(Canvas c){float space=dp(32);cell=Math.min((getWidth()-dp(12))/6f,(getHeight()-space*2)/6f);left=(getWidth()-6*cell)/2;top=space;c.drawColor(bg);for(int at=0;at<total;at++){float x=left+(at%n)*cell,y=top+(at/n)*cell;p.setColor(steps.contains(at)?0xff164f4b:surface);c.drawRect(x,y,x+cell,y+cell,p);}p.setColor(accent);p.setStrokeWidth(dp(4));for(int i=1;i<steps.size();i++){int a=steps.get(i-1),b=steps.get(i);c.drawLine(left+(a%n+.5f)*cell,top+(a/n+.5f)*cell,left+(b%n+.5f)*cell,top+(b/n+.5f)*cell,p);}for(int at=0;at<total;at++){float x=left+(at%n)*cell,y=top+(at/n)*cell;p.setColor(0xff9aadc1);p.setStrokeWidth(dp(2));if((walls[at]&1)!=0&&at!=0)c.drawLine(x,y,x+cell,y,p);if((walls[at]&2)!=0)c.drawLine(x+cell,y,x+cell,y+cell,p);if((walls[at]&4)!=0&&at!=total-1)c.drawLine(x,y+cell,x+cell,y+cell,p);if((walls[at]&8)!=0)c.drawLine(x,y,x,y+cell,p);p.setColor(at==steps.get(steps.size()-1)?accent:fg);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(Math.min(dp(18),cell*.25f));c.drawText(labels[at],x+cell/2,y+cell/2+dp(5),p);}p.setColor(accent);p.setTextSize(dp(15));c.drawText("START",left+cell/2,top-dp(10),p);p.setColor(0xffff8797);c.drawText("END",left+cell*5.5f,top+cell*6+dp(23),p);}
 public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_UP){int x=(int)((e.getX()-left)/cell),y=(int)((e.getY()-top)/cell);if(e.getX()>=left&&e.getY()>=top&&x>=0&&y>=0&&x<n&&y<n)move(y*n+x);performClick();}return true;}
 public boolean performClick(){super.performClick();return true;}
 }
}
